result:
	.setUpTop{
		height: 6px;
		background: rgb(240, 242, 245);
	}
	.setUp{
		display flex;
		justify-content space-between;
		align-items center;
		height: 56px;
		padding: 0 15px;

		.label{
			font-size: 16px;
			color: #333333;
		}

		.title{
			width: 140px;
			height: 28px;
			background: #F9F9F9;
			border-radius: 14px;
			line-height: 28px;
			font-size: 12px;
			color: #333333;
			.item{
				width: 50%;
				text-align: center;
				cursor: pointer;
				&.on{
					width: 70px;
					background: #1890FF;
					border-radius: 14px;
					color: #FFFFFF;
					font-size: 12px;
				}
			}
		}
	}
    .setUp /deep/.ivu-tabs-nav-scroll{
        padding 0 30px;
    }
    .setUp /deep/.ivu-tabs-nav .ivu-tabs-tab{
        padding: 8px 45px;
    }
